import { API_ROUTES } from "@nexa-chess/types";
import type { User } from "@prisma/client";
import type { createWorld } from "./world";

// Shared by cross-user-access.int-spec.ts (two users of one academy) and
// cross-academy-access.int-spec.ts (docs/SAAS_MULTI_TENANCY.md § "Phase 3
// plan", slice 7).

export type World = Awaited<ReturnType<typeof createWorld>>;
export type Case = {
  name: string;
  as: (w: World) => User;
  method?: "GET" | "PATCH" | "POST" | "PUT" | "DELETE";
  path: (w: World) => string;
  body?: unknown | ((w: World) => unknown);
};

const DUE_TOMORROW = () => new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();

// Every route here has a twin in OWN_CASES on the caller's own data (where a
// GET exists), so a denial can't pass just because the route itself is broken.
