export function rushReport(rushId: string) {
  return {
    bestCombo: 0,
    clockEndsAt: null,
    errors: 0,
    finished: false,
    highestRating: null,
    moves: 1,
    puzzleIndex: 0,
    rushId,
    score: 0,
    skipsUsed: 0,
    solved: 0
  };
}

